<?php require_once '../config/auth.php';$page_title='Deal';$base='../';$id=(int)($_GET['id']??0);$customers=$pdo->query('SELECT id,name FROM customers ORDER BY name')->fetchAll();$r=['title'=>'','customer_id'=>'','amount'=>0,'stage'=>'prospecting','expected_close'=>'','probability'=>20,'notes'=>''];if($id){$s=$pdo->prepare('SELECT * FROM deals WHERE id=?');$s->execute([$id]);$r=$s->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){$d=[trim($_POST['title']),(int)$_POST['customer_id'],(float)$_POST['amount'],$_POST['stage'],$_POST['expected_close']?:null,(int)$_POST['probability'],trim($_POST['notes'])];if($id)$pdo->prepare('UPDATE deals SET title=?,customer_id=?,amount=?,stage=?,expected_close=?,probability=?,notes=? WHERE id=?')->execute([...$d,$id]);else$pdo->prepare('INSERT INTO deals(title,customer_id,amount,stage,expected_close,probability,notes,owner_id) VALUES(?,?,?,?,?,?,?,?)')->execute([...$d,$_SESSION['user_id']]);header('Location:index.php');exit;}include '../partials/header.php';?><div class="cardx"><h4><?=$id?'Edit':'Create'?> Deal</h4><form method="post"><div class="row g-3 mt-1"><div class="col-md-7"><label>Deal title</label><input required class="form-control" name="title" value="<?=e($r['title'])?>"></div><div class="col-md-5"><label>Customer</label><select required class="form-select" name="customer_id"><option value="">Select</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=$r['customer_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Amount</label><input class="form-control" type="number" step=".01" name="amount" value="<?=e($r['amount'])?>"></div><div class="col-md-4"><label>Stage</label><select class="form-select" name="stage"><?php foreach(['prospecting','qualified','proposal','negotiation','won','lost'] as $x):?><option <?=$r['stage']==$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Probability %</label><input class="form-control" type="number" min="0" max="100" name="probability" value="<?=e($r['probability'])?>"></div><div class="col-md-6"><label>Expected close</label><input class="form-control" type="date" name="expected_close" value="<?=e($r['expected_close'])?>"></div><div class="col-12"><label>Notes</label><textarea class="form-control" name="notes"><?=e($r['notes'])?></textarea></div></div><button class="btn btn-primary mt-4">Save deal</button></form></div><?php include '../partials/footer.php';?>